  up_hp_desc:{tr:"Her oyuna daha fazla canla başlarsın.",en:"Start every run with more HP.",de:"Starte jeden Lauf mit mehr LP.",fr:"Commence chaque partie avec plus de PV.",es:"Empieza cada partida con más vida.",pt:"Comece cada partida com mais vida.",it:"Inizia ogni partita con più vite.",ru:"Начинай каждый забег с бо́льшим запасом HP.",ar:"ابدأ كل جولة بصحة أكثر.",ja:"毎回より多いHPでスタート。",ko:"매 판 더 많은 체력으로 시작합니다.",zh:"每局开始时拥有更多生命值。",hi:"हर खेल ज़्यादा HP के साथ शुरू करो।",id:"Mulai setiap permainan dengan HP lebih banyak.",pl:"Zaczynaj każdą grę z większą liczbą PŻ."},
  up_coinpct_desc:{tr:"Kazandığın tüm notalar yüzde olarak artar.",en:"Boosts every note you earn by a percentage.",de:"Erhöht alle verdienten Noten prozentual.",fr:"Augmente en pourcentage toutes les notes gagnées.",es:"Aumenta en porcentaje todas las notas que ganas.",pt:"Aumenta em porcentagem todas as notas que você ganha.",it:"Aumenta in percentuale tutte le note che guadagni.",ru:"Увеличивает все получаемые ноты на процент.",ar:"يزيد كل النوتات التي تكسبها بنسبة مئوية.",ja:"獲得する音符すべてが割合で増える。",ko:"획득하는 모든 음표가 비율만큼 늘어납니다.",zh:"按百分比提高你获得的所有音符。",hi:"तुम्हारे कमाए सभी नोट्स प्रतिशत में बढ़ते हैं।",id:"Semua not yang kamu dapat bertambah sekian persen.",pl:"Zwiększa procentowo wszystkie zdobywane nuty."},
  up_itemcoin_desc:{tr:"Her nota parçacığı daha çok nota verir.",en:"Each note particle gives more notes.",de:"Jedes Noten-Teilchen gibt mehr Noten.",fr:"Chaque particule de note rapporte plus de notes.",es:"Cada partícula de nota da más notas.",pt:"Cada partícula de nota dá mais notas.",it:"Ogni particella di nota dà più note.",ru:"Каждая нотная частица даёт больше нот.",ar:"كل جسيم نوتة يمنح نوتات أكثر.",ja:"音符パーティクル1つで得る音符が増える。",ko:"음표 파티클 하나당 더 많은 음표를 줍니다.",zh:"每个音符粒子给予更多音符。",hi:"हर नोट कण ज़्यादा नोट्स देता है।",id:"Setiap partikel not memberi lebih banyak not.",pl:"Każda cząstka nutowa daje więcej nut."},
  up_boostdur_desc:{tr:"Yavaşlatma, mıknatıs ve çarpan daha uzun sürer.",en:"Slow, magnet and multiplier last longer.",de:"Zeitlupe, Magnet und Multiplikator halten länger.",fr:"Ralenti, aimant et multiplicateur durent plus longtemps.",es:"Ralentizar, imán y multiplicador duran más.",pt:"Lentidão, ímã e multiplicador duram mais.",it:"Rallentamento, magnete e moltiplicatore durano di più.",ru:"Замедление, магнит и множитель длятся дольше.",ar:"الإبطاء والمغناطيس والمضاعف تدوم أطول.",ja:"スロー・マグネット・倍率が長く続く。",ko:"슬로우, 자석, 배율이 더 오래 지속됩니다.",zh:"减速、磁铁和倍增持续更久。",hi:"स्लो, मैग्नेट और मल्टीप्लायर ज़्यादा देर चलते हैं।",id:"Lambat, magnet, dan pengganda bertahan lebih lama.",pl:"Spowolnienie, magnes i mnożnik działają dłużej."},
  up_shieldpower_desc:{tr:"Kalkan kırılmadan önce daha çok çarpışma emer.",en:"Your shield absorbs more hits before breaking.",de:"Dein Schild fängt mehr Treffer ab, bevor er bricht.",fr:"Ton bouclier encaisse plus de coups avant de se briser.",es:"Tu escudo absorbe más golpes antes de romperse.",pt:"Seu escudo absorve mais golpes antes de quebrar.",it:"Il tuo scudo assorbe più colpi prima di rompersi.",ru:"Щит выдерживает больше ударов, прежде чем сломаться.",ar:"يمتص درعك ضربات أكثر قبل أن ينكسر.",ja:"シールドが壊れるまでに防げる回数が増える。",ko:"실드가 깨지기 전에 더 많은 충돌을 막습니다.",zh:"护盾破碎前能抵挡更多次撞击。",hi:"शील्ड टूटने से पहले ज़्यादा वार झेलती है।",id:"Perisaimu menahan lebih banyak pukulan sebelum pecah.",pl:"Tarcza przyjmuje więcej trafień, zanim pęknie."},
  up_multpower_desc:{tr:"Çarpan takviyesi puanını daha çok katlar.",en:"The multiplier pickup multiplies your score more.",de:"Der Multiplikator vervielfacht deine Punkte stärker.",fr:"Le multiplicateur multiplie davantage ton score.",es:"El multiplicador multiplica más tus puntos.",pt:"O multiplicador multiplica mais seus pontos.",it:"Il moltiplicatore moltiplica di più il tuo punteggio.",ru:"Множитель сильнее умножает твои очки.",ar:"يضاعف المضاعفُ نقاطك أكثر.",ja:"倍率アイテムのスコア倍率が上がる。",ko:"배율 아이템이 점수를 더 크게 곱합니다.",zh:"倍增道具让你的分数倍率更高。",hi:"मल्टीप्लायर तुम्हारा स्कोर और ज़्यादा गुणा करता है।",id:"Pengganda melipatgandakan skormu lebih besar.",pl:"Mnożnik mocniej mnoży twoje punkty."},
